const freshState=()=>({role:'customer',screen:0,view:'focus',package:'serengeti',filter:'all',search:'',saved:[],date:'2026-11-12',adults:2,children:0,pickup:'Arusha hotel',special:'Vegetarian meal for one traveler',travelers:['Alice Morgan','Daniel Morgan'],booking:false,payment:'deposit',method:'card',paid:0,confirmed:false,assigned:false,vehicle:'TZ-001',guide:'Kelvin Mushi',pickupTime:'07:30',detailTab:'itinerary',day:0,customDest:['Serengeti'],budget:1500,style:'Mid-range',customNotes:'A relaxed pace with time for photography',customSubmitted:false,quoteSent:false,quoteSaved:false,quoteAccepted:false,lodge:'Savanna tented lodge',quoteNotes:'Private game drives and a relaxed afternoon at the lodge.',tripProgress:0,issueType:'Vehicle issue',issueNotes:'',issueReported:false,handover:'',tripComplete:false,assignedTab:'today',published:{serengeti:true,zanzibar:true,kilimanjaro:true},maintenance:false,notifications:{email:true,sms:false,push:true},financeAccess:false,audit:[],opsUpdate:false,review:0});
