const packageNow=()=>state.customMode?{...packages[state.package],name:'Your tailor-made safari',place:state.customDest.join(' + '),days:5,price:state.budget}:packages[state.package];
const total=()=>packageNow().price*state.adults+Math.round(packageNow().price*.7)*state.children;
const amountDue=()=>state.payment==='deposit'?Math.round(total()*.3):total();
const balance=()=>Math.max(0,total()-state.paid);
const bookingStatus=()=>state.confirmed?'Confirmed':state.booking?(state.paid?'Ready for review':'Awaiting deposit'):'Not booked yet';
const dateLabel=()=>new Date(state.date+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
